INSERT INTO existing_system_roles(name) SELECT name FROM roles WHERE name IN ('guest','user','admin','superadmin');
INSERT INTO roles(name, description, is_system) VALUES ('guest','Newly registered, pending approval',1) ON CONFLICT DO NOTHING;
INSERT INTO roles(name, description, is_system) VALUES ('user','Standard warehouse operator',1) ON CONFLICT DO NOTHING;
INSERT INTO roles(name, description, is_system) VALUES ('admin','Full access including user and role management',1) ON CONFLICT DO NOTHING;
INSERT INTO roles(name, description, is_system) VALUES ('superadmin','Unrestricted system access (env-configured)',1) ON CONFLICT DO NOTHING;
INSERT INTO newly_seeded_roles(id,name) SELECT id,name FROM roles WHERE name IN ('user','admin') AND name NOT IN (SELECT name FROM existing_system_roles);
INSERT INTO role_permissions(role_id,permission) SELECT r.id,p.permission FROM newly_seeded_roles r JOIN (SELECT 'user' name,'design:read' permission UNION ALL SELECT 'user','preset:read' UNION ALL SELECT 'user','accurate:read' UNION ALL SELECT 'user','accurate:create' UNION ALL SELECT 'user','accurate:update' UNION ALL SELECT 'user','accurate:delete' UNION ALL SELECT 'user','system:read' UNION ALL SELECT 'admin','design:read' UNION ALL SELECT 'admin','design:create' UNION ALL SELECT 'admin','design:update' UNION ALL SELECT 'admin','design:delete' UNION ALL SELECT 'admin','preset:read' UNION ALL SELECT 'admin','preset:create' UNION ALL SELECT 'admin','preset:update' UNION ALL SELECT 'admin','preset:delete' UNION ALL SELECT 'admin','accurate:read' UNION ALL SELECT 'admin','accurate:create' UNION ALL SELECT 'admin','accurate:update' UNION ALL SELECT 'admin','accurate:delete' UNION ALL SELECT 'admin','accurate_account:read' UNION ALL SELECT 'admin','accurate_account:create' UNION ALL SELECT 'admin','accurate_account:update' UNION ALL SELECT 'admin','accurate_account:delete' UNION ALL SELECT 'admin','user:read' UNION ALL SELECT 'admin','user:create' UNION ALL SELECT 'admin','user:update' UNION ALL SELECT 'admin','user:delete' UNION ALL SELECT 'admin','role:read' UNION ALL SELECT 'admin','role:create' UNION ALL SELECT 'admin','role:update' UNION ALL SELECT 'admin','role:delete' UNION ALL SELECT 'admin','system:read') p ON p.name=r.name ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,'accurate_account:read' FROM roles WHERE name='admin' AND NOT EXISTS(SELECT 1 FROM migration_markers WHERE name='accurate_account_permissions_v1') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,'accurate_account:create' FROM roles WHERE name='admin' AND NOT EXISTS(SELECT 1 FROM migration_markers WHERE name='accurate_account_permissions_v1') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,'accurate_account:update' FROM roles WHERE name='admin' AND NOT EXISTS(SELECT 1 FROM migration_markers WHERE name='accurate_account_permissions_v1') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,'accurate_account:delete' FROM roles WHERE name='admin' AND NOT EXISTS(SELECT 1 FROM migration_markers WHERE name='accurate_account_permissions_v1') ON CONFLICT DO NOTHING;
INSERT INTO migration_markers(name) SELECT 'accurate_account_permissions_v1' WHERE NOT EXISTS(SELECT 1 FROM migration_markers WHERE name='accurate_account_permissions_v1');
